const cfg = $('Settings').first().json.config;
const since = Date.now() - Number(cfg.hours_back || 24) * 3600000;
const kws = (cfg.keywords || []).map((k) => String(k).toLowerCase()).filter(Boolean);
const seen = new Set();
const items = [];
for (const { json: it } of $input.all()) {
  if (!it || !it.link || it.error) continue;
  const t = Date.parse(it.isoDate || it.pubDate || '');
  if (!isNaN(t) && t < since) continue;
  if (seen.has(it.link)) continue;
  const text = String((it.title || '') + ' ' + (it.contentSnippet || it.content || '')).replace(/<[^>]+>/g, ' ');
  if (kws.length && !kws.some((k) => text.toLowerCase().includes(k))) continue;
  seen.add(it.link);
  items.push({ title: String(it.title || '').trim(), link: it.link, published: it.isoDate || it.pubDate || '',
    source: String(it.creator || it.author || '').trim(), snippet: text.replace(/\s+/g, ' ').trim().slice(0, 800) });
}
const top = items.slice(0, Number(cfg.max_items) || 20);
if (!top.length) return [];
return [{ json: { count: top.length,
  items_text: top.map((i, n) => `${n + 1}. ${i.title}\n${i.snippet}\n${i.link}`).join('\n\n'),
  links: top.map((i, n) => `${n + 1}. ${i.title}\n   ${i.link}`).join('\n') } }];

