const cfg = $('Settings').first().json.config;
const key = (k) => String(k).trim().toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');
const title = (s) => s.replace(/\s+/g, ' ').trim().toLowerCase().replace(/(^|[\s'-])\p{L}/gu, (m) => m.toUpperCase());
const seen = new Set();
const out = [];
for (const { json: raw } of $input.all()) {
  const r = {};
  for (const [k, v] of Object.entries(raw)) r[key(k)] = String(v ?? '').replace(/\s+/g, ' ').trim();
  if (r.email !== undefined) { r.email = r.email.toLowerCase(); if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(r.email)) r.email = ''; }
  for (const c of ['name', 'first_name', 'last_name', 'city']) if (r[c]) r[c] = title(r[c]);
  if (r.phone !== undefined) r.phone = r.phone.replace(/[^\d+]/g, '');
  if ((cfg.required_columns || []).some((c) => !r[c])) continue;
  const id = JSON.stringify(r);
  if (seen.has(id)) continue;
  seen.add(id);
  out.push({ json: r });
}
return out;
